def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """

    new_cmd = []

    if cmd:
        try:
            import os
            executable = os.path.abspath(cmd[0])
        except (ImportError, ValueError):
            new_cmd.extend(cmd)
            return tuple(new_cmd)

        if executable.startswith('/') or executable.startswith('\\'):
            executable = executable[1:]

        try:
            startswith_rlx = executable.startswith(r'(launch)'
        except AttributeError:
            startswith_rlx = executable.startswith('(') and executable.endswith(')')

        if startswith_rlx:
            executable = executable[1:-1]

        new_cmd.append(executable)

        # If the executable is a deep path, prepend its dir to the path
        if os.path.dirname(executable):
            executable = os.path.dirname(executable) + os.path.sep + executable

        new_cmd.append(executable) if executable != cmd[0] else []

    return tuple(new_cmd)
