import functools
from time import monotonic

@functools.lru_cache(maxsize=maxsize, typed=typed)
def ttl_cache(maxsize=128, ttl=600, timer=monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def wrapper(func):
        @functools.wraps(func)
        def memoized_func(*args, **kwargs):
            cache_key = args, frozenset(sorted(kwargs.items()))
            timestamp = timer()
            if cache_key in memoized_func.cache:
                cached_value, cached_timestamp = memoized_func.cache[cache_key]
                if timestamp - cached_timestamp < ttl:
                    return cached_value
                else:
                    del memoized_func.cache[cache_key]
            result = func(*args, **kwargs)
            memoized_func.cache[cache_key] = (result, timestamp)
            return result
        memoized_func.cache = {}
        return memoized_func
    return wrapper
