def _legacy_mergeOrderings(orderings: List[List[int]]) -> List[int]:
    order_map = defaultdict(int)
    for ordering in orderings:
        for item in ordering:
            order_map[item] += 1

    merge_ordering = []
    for ordering in orderings:
        for item in ordering:
            if order_map[item] > 1:
                merge_ordering.extend(ordering[ordering.index(item):])
                break
            elif item not in merge_ordering:
                merge_ordering.append(item)

    return merge_ordering
