def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
        {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    # Collect errors
    error_indices = []
    if hasattr(self, "error"):
        index = 0
        for field in ["E", "t"]:
            if hasattr(self, field):
                error_indices.extend([i + index] for i, _ in enumerate(getattr(self, field)))
                index += len(getattr(self, field))
    context.error.extend(error_indices)

    # Update context with graph properties
    if "value" in context and isinstance(context.value, dict):
        for field in ["E", "t", "error_E_low"]:  # Assuming E, t, x_low are the fields
            if hasattr(self, field):
                if field not in context.value:
                    context.value[field] = []
                if isinstance(getattr(self, field), list):
                    context.value[field].extend(getattr(self, field))
                elif isinstance(getattr(self, field), dict):
                    if field not in context.value:
                        context.value[field] = {}
                    for subfield in ["value", "error", "error_E_low"]:
                        if isinstance(getattr(self, field)[subfield], list):
                            context.value[field][subfield].extend(getattr(self, field)[subfield])
