        elif isinstance(value, list):
            if not all(isinstance(v, str) for v in value):
                raise ValidationError(label=key, message='expected list of strings or bytes-like objects')
            if not all(bool(re.match(v, self.REGEXES.get(key), re.IGNORECASE)) for v in value):
                raise ValidationError(label=key, message='expected list of strings or bytes-like objects')
        elif value:
