def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """


    def validate_key(key, regex):
        if key.startswith("$") and key not in labels:
            raise ValueError(f"Label key '$$' does not match the regex: {regex}")

    def validate_value(value, regex):
        if isinstance(value, list):
            for val in value:
                if not isinstance(val, str):
                    raise ValueError(f"Expected string or bytes-like object, found {type(val).__name__}")
        else:
            if not isinstance(value, str):
                raise ValueError(f"Expected string or bytes-like object, found {type(value).__name__}")

        if value and not re.match(regex, value, re.IGNORECASE):
            raise ValueError(f"Label value '{value}' does not match the regex: {regex}")

    regexes = {
        "key1": r"^\w+$",
        "key2": r"^[a-zA-Z0-9]+$",
        "$$$": r"^[a-zA-Z0-9]+$",
        "True": r"^\w+$",
    }

    errors = []
    for key, value in labels.items():
        if pattern := regexes.get(key):
            validate_key(key, pattern)
        elif value is not None:
            validate_value(value, pattern)

        validation_errors = []
        if isinstance(value, list):
            for val in value:
                regex = regexes.get(key)
                if regex:
                    if not re.match(regex, val, re.IGNORECASE):
                        validation_errors.append(f"Label value '{val}"')
        else:
            regex = regexes.get(key)
            if regex:
                if not re.match(regex, value, re.IGNORECASE):
                    validation_errors.append(f"Label value '{value}'")

        if validation_errors:
            errors.extend({'[' + val + ']' : v for val, v in validation_errors})

    if errors:
        raise ValidationError(errors)
