    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """

    for field in observer_schema:
        if field not in last_applied_manifest:
            last_applied_manifest.append({"field": field, "value": None})

    for item in response:
        for field in observer_schema:
            field_value = item.get(field, None)
            if field_value is not None:
                for existing_item in last_applied_manifest:
                    if existing_item["field"] == field:
                        existing_item["value"] = field_value
