def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not inventory or not isinstance(inventory, dict):
        raise ValueError("Invalid inventory")

    if not extract_spec_version:
        if 'type' not in inventory:
            raise ValueError("No type specified in the inventory")

        if not isinstance(inventory['type'], tuple) or len(inventory['type']) != 2:
            raise ValueError("Invalid type specification in the inventory")

        spec_version = inventory['type'][1]
        if not isinstance(spec_version, str):
            raise ValueError("Invalid type specification version in the inventory")

        if self.spec_version and spec_version != self.spec_version:
            raise ValueError("Invalid specification version in the inventory. Expected " + self.spec_version + ", got " + spec_version + ".")

        if inventory['type'][0] in ['document', 'annotation']:
            #if document or annotation quick check
            return True
        elif inventory['type'][0] in ['structure', 'embedded_annotation']:
            #if structure or embedded annotation need to recurse
            #check all kids
            for key, value in inventory.items():
                if key != 'type':
                    if not self.validate(value, True):
                        return False
            return True
        else:
            return False
