def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    text = Tabs(indent) + f'<{self.__class__.__name__} '
    attrs = []
    if self.id:
        attrs.append(f'id={self.id}')
    if self.constant:
        attrs.append(f'constant={self.constant}')
    if self.required:
        attrs.append(f'required={self.required}')
    if attrs:
        text += ' ' + ' '.join(attrs)
    text += '>'
    for child in self:
        if isinstance(child, str):
            text += f'\n{Tabs(indent+2)}<{child}>'
        else:
            text += f'\n{Tabs(indent+2)}<{child.__class__.__name__}'.rstrip('>')
            if hasattr(child, 'pretty'):
                text += child.pretty(indent+4)
            else:
                text += f'>{Tabs(indent+4)}/>'
    text += f'\n{Tabs(indent)}</{self.__class__.__name__}>'
    if debug:
        return f'{text}\n'
    return text.strip()
