def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.

    :param indent: Indentation level for each line
    :type indent: int
    :param debug: Whether to enable debug mode
    :type debug: bool
    :return: A pretty formatted string
    :rtype: str
    """
    result = ""
    if indent:
        result += " " * indent + self.__class__.__name__ + ":\n"
    else:
        result += self.__class__.__name__ + ":\n"
    if self.children:
        for child in self.children:
            result += child.pretty(indent + 4, debug)
    if self.attribs:
        for key, value in self.attribs.items():
            if debug:
                result += " " * (indent + 4) + key + ": " + str(value) + "\n"
            else:
                result += " " * (indent + 4) + key + "\n"
    return result
