def absorb(self, args):
    """Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

            A & (A | B) = A, A | (A & B) = A

    Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from typing import *
    from .structures import *

    result = []
    for arg in args:
        lhs, operation, rhs = arg
        new_lhs = None
        new_rhs = None

        if operation == '&':
            if isinstance(lhs, Literal) and lhs.value:
                new_lhs = Literal(lhs.value)
            if isinstance(rhs, Literal) and rhs.value:
                new_rhs = Literal(rhs.value)
        elif operation == '|':
            if isinstance(lhs, Literal) and not lhs.value:
                new_lhs = Literal(lhs.value)
            if isinstance(rhs, Literal) and not rhs.value:
                new_rhs = Literal(rhs.value)
        elif operation == '~':
            if isinstance(lhs, Literal) and not lhs.value:
                new_lhs = Literal(lhs.value)
            if isinstance(rhs, Literal) and lhs.value:
                new_rhs = Literal(lhs.value)

        if isinstance(new_lhs, Literal) and isinstance(new_rhs, Literal):
            result.append(Literal(lhs.value or rhs.value))
        elif isinstance(new_lhs, Literal):
            result.append(new_lhs)
        elif isinstance(new_rhs, Literal):
            result.append(new_rhs)
        else:
            result.append(arg)

    return result
```

