    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def wrapper(*args, **kwargs):
        if sys.version_info[0] == 2:
            return namefunc(*args, **kwargs).encode('utf-8')
        return namefunc(*args, **kwargs)
