def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # This method checks if the storage root hierarchy is valid
    # If validate_objects is False, it only checks if the root has the required children
    # If check_digests is False, it skips checking the digests of the objects
    # If show_warnings is True, it prints warnings

    num_objects = 0
    good_objects = 0

    # Start by checking if the root has the required children
    if not validate_objects:
        if not hasattr(self, 'child1') or not hasattr(self, 'child2') or not hasattr(self, 'child3'):
            if show_warnings:
                print("Warning: The storage root does not have the required children.")
            return num_objects, good_objects

    num_objects += 1
    child1 = getattr(self, 'child1')
    if child1:
        if child1.validate_hierarchy(validate_objects, check_digests, show_warnings):
            good_objects += 1
        else:
            show_warnings(f"Error: The first child of the storage root is not valid.")

    num_objects += 1
    child2 = getattr(self, 'child2')
    if child2:
        if child2.validate_hierarchy(validate_objects, check_digests, show_warnings):
            good_objects += 1
        else:
            show_warnings(f"Error: The second child of the storage root is not valid.")

    num_objects += 1
    child3 = getattr(self, 'child3')
    if child3:
        if child3.validate_hierarchy(validate_objects, check_digests, show_warnings):
            good_objects += 1
        else:
            show_warnings(f"Error: The third child of the storage root is not valid.")

    # Check the digests if the option is enabled
    if check_digests:
        for child in self.children:
            if child.check_digests():
                good_objects += 1
            else:
                show_warnings(f"Warning: The digest of the child {child.__class__.__name__} is invalid.")

    # Return the number of objects checked and the number of objects that were found to be valid
    return num_objects, good_objects
