def next_version(self):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """


    if self.version.startswith('v'):
        pattern = r'ver(\d+)'
        version_match = re.search(pattern, self.version)
        if version_match:
            new_version = f'ver{int(version_match.group(1)) + 1}'
            return new_version
        else:
            return "v1"
    else:
        pattern = r'(\d+).(\d+)'
        match = re.search(pattern, self.version)
        if match:
            major, minor = int(match.group(1)), int(match.group(2))
            new_version = f'{major}.{minor + 1}.{self.flight_number}'
            return new_version
        else:
            return self.version
