def deep_merge_nodes(nodes):
    result = []
    seen = defaultdict(list)
    for key, value in nodes:
        if key.asplain() in seen:
            seen[key.asplain()].append(value)
        else:
            seen[key.asplain()].append([value])

    for keys, values in seen.items():
        if len(values) > 1:
            current_value = values.pop(0)
            for value in values:
                result.append((key, value))
            result.append((key, current_value))
        else:
            result.append((key, values[0]))

