from ruamel.yaml.nodes import MapNode, ScalarNode

def deep_merge_nodes(nodes):
    merged = {}
    duplicate_keys = set()

    for key, value in nodes:
        if isinstance(value, MapNode):
            if key not in merged:
                merged[key] = value
            else:
                number_occurrences = merged[key].content.count(ScalarNode)
                if number_occurrences > 1:
                    # If there are multiple occurrences of a scalar node, we keep the last one
                    continue
                # Deep merge nested maps
                merged[key] = deep_merge_nodes(merged[key].content + value.content)
        else:
            if key in merged:
                if isinstance(merged[key], MapNode):
                    if isinstance(value, MapNode):
                        number_occurrences = merged[key].content.count(ScalarNode)
                        if number_occurrences > 1:
                            # If there are multiple occurrences of a scalar node, we keep the last one
                            continue
                        # Deep merge nested maps
                        merged[key] = deep_merge_nodes(merged[key].content + value.content)
                    else:
                        # If merged key is a scalar, and value is not, we replace the scalar with the most recent
                        merged[key] = value
                else:
                    # If merged key is not a scalar, and value is not a scalar, we replace the merged key with the last value
                    merged[key] = value
            else:
                merged[key] = value

    return list(merged.items())
