from ruamel.yaml.nodes import MappingNode, ScalarNode

def deep_merge_nodes(nodes: List[Tuple[ScalarNode, MappingNode]]) -> List[Tuple[ScalarNode, MappingNode]]:
    merged_nodes = {}
    for key, value in nodes:
        if key in merged_nodes:
            # Merge values for the same key
            if isinstance(merged_nodes[key][1], MappingNode):
                if isinstance(value[1], MappingNode):
                    # Merging mappings within each key
                    merged_nodes[key] = (merged_nodes[key][0], deep_merge_nodes([(key, node) for key, node in value[1].items()]))
                else:
                    # Overriding non-Mapping values
                    merged_nodes[key] = (merged_nodes[key][0], value[1])
            else:
                # Overriding non-Mapping values
                merged_nodes[key] = (merged_nodes[key][0], value)
        else:
            # Just add new keys and values
            merged_nodes[key] = value

    return list(merged_nodes.values())
