def parse_subparser_arguments(unparsed_arguments, subparsers):
    if not len(unparsed_arguments) or len(unparsed_arguments) % 2 != 0:
        raise ValueError("Invalid number of_arguments")
    my_namespace = {}
    not_claimed_arguments = [];
    for i in range(0,len(unparsed_arguments),2):
        subparser_name = unparsed_arguments[i]
        if subparser_name not in subparsers:
            raise ValueError("Unknown subparser: " + subparser_name)
        namespace = subparsers[subparser_name].parse_args(unparsed_arguments[i+1:])
        my_namespace[subparser_name] = namespace
        not_claimed_arguments.append(unparsed_arguments[i+1:])
    return my_namespace, not_claimed_arguments
