def vertex3tuple(vertices):
    """return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    """
    if len(vertices) < 3:
        raise ValueError("Input must have at least 3 vertices")
    points = []
    for i in range(len(vertices)):
        if i == 0:
            points.append((vertices[-1], vertices[i], vertices[i+1]))
        elif i == len(vertices) - 1:
            points.append((vertices[i-1], vertices[i], vertices[0]))
        else:
            points.append((vertices[i-1], vertices[i], vertices[i+1]))
    return points
