    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """

    # Define platform-specific splitting patterns
    if platform == 'this':
        pattern = r'[\s\'"]+'
    elif platform == 1:
        pattern = r'[\s;,\t]+'
    elif platform == 0:
        pattern = r'[\s;,\t]+'
    else:
        raise ValueError("Invalid platform value. Must be 'this', 1, or 0.")

    return re.split(pattern, s)
