import datetime

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''

    if frequency is None or frequency == "always":
        return None

    frequency_value, time_unit = frequency.split()
    try:
        frequency_value = int(frequency_value)
    except ValueError:
        raise ValueError(f"Invalid frequency value: '{frequency}'")

    if time_unit == "seconds":
        return datetime.timedelta(seconds=frequency_value)
    elif time_unit == "minutes":
        return datetime.timedelta(minutes=frequency_value)
    elif time_unit == "hours":
        return datetime.timedelta(hours=frequency_value)
    elif time_unit == "days":
        return datetime.timedelta(days=frequency_value)
    elif time_unit == "weeks":
        return datetime.timedelta(weeks=frequency_value)
    elif time_unit == "months":
        # Note: This can be approximated using days, but precision is lost
        return datetime.timedelta(days=frequency_value * 30)
    elif time_unit == "years":
        # Note: This can be approximated using days, but precision is lost
        return datetime.timedelta(days=frequency_value * 365)
    else:
        raise ValueError(f"Invalid time unit: '{time_unit}'")
