from datetime import timedelta, parse
import re

def parse_frequency(frequency):
    '''    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''

    if frequency is None or frequency.lower() == 'always':
        return None

    if not re.match(r'^[0-9]+ (\w+)$', frequency):
        raise ValueError("Invalid frequency string: {}".format(frequency))

    match = re.match(r'^([0-9]+) (\w+)$', frequency)
    amount = int(match.group(1))
    unit = match.group(2)

    if unit == 'weeks':
        return timedelta(weeks=amount)
    elif unit == 'days':
        return timedelta(days=amount)
    elif unit == 'hours':
        return timedelta(hours=amount)
    elif unit == 'minutes':
        return timedelta(minutes=amount)
    elif unit == 'seconds':
        return timedelta(seconds=amount)
    else:
        raise ValueError("Unsupported unit: {}".format(unit))
