import re

def make_find_paths(find_paths):
    patterns = []
    for path in find_paths:
        if isinstance(path, str):
            if re.match(r'(sh:\*\/*(?:.*\\*${})*\/)*{}/', path):
                patterns.append(path.replace('{/}', '/'))
            else:
                patterns.append(path)
        elif isinstance(path, list):
            patterns.append(make_find_paths(path))
        else:
            raise ValueError("Invalid type for find path")
    return patterns

