def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    if matcher.prefix in os.environ:
        return os.environ[matcher.prefix]
    elif matcher.prefix in os.sys.getenv().values():
        return next(value for key, value in os.sys.getenv().items() if key == matcher.prefix)
    else:
        if matcher.default is None:
            raise KeyError(matcher.prefix)
        return matcher.default
