import subprocess
def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    try:
        if verbose:
            print(f"Running command: {commands} {args}")
        result = subprocess.run([commands] + args, cwd=cwd, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env, check=True)
        if hide_stderr: return result.stdout
        return {"stdout": result.stdout, "stderr": result.stderr}
    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Error running command: {commands} {args}")
            print(f"stdout: {e.stdout}")
            print(f"stderr: {e.stderr}")
        if hide_stderr: 
            return {"stdout": e.stdout}
        return {"stderr": e.stderr, "error": str(e)}
