def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    if roots is None:
        roots = set()

    subject = None
    for child in graph.objects(predicate=prop):
        if subject is None:
            subject = child
        else:
            # check if child is a subclass of the current subject
            if graph.is_subclass_of(child=child, superclass=subject):
                roots.add(child)
                # continue search with child as new starting point
                root = child
            else:
                # skip non-subclasses
                continue

    return roots
