from typing import *
from rdflib import *
from rdflib.graph import Graph, Literal, consume, URIRef

def find_roots(graph: Graph, prop: URIRef, roots: Set[Node] = None) -> Set[Node]:
    if not hasattr(graph, "bnode_id_counter"): graph.bnode_id_counter = 0

    if roots is None: roots = set()
    from collections.abc import Set
    import weakref
    if not isinstance(roots, Set): roots = set(roots)
    seen = weakref.WeakSet()

    def process(x, y):
        if x in seen: return
        seen.add(x)
        if y not in roots:
            roots.add(y)

    def visit(parent: URIRef, child: URIRef):
        process(parent, child)
        for s, p, o in graph.triples((parent, prop, child)):
            if isinstance(s, BNode): continue
            visit(o, child)
        # process(child, parent)

    top = None
    for subj, pred, obj in graph.triples((None, RDF.type, RDF.Property()), [(None, RDF.type, BNode()))]:
        if not top: top = subj
        elif not pred: top = subj

    # could also consider all BNodes and recurse, but it's not necessary
    # for subclass search when prop is RDFS.subClassOf
    for root in (top,):
        visiting = set([root])
        while visiting:
            parent = visiting.pop()
            for s, p, o in graph.triples((parent, prop, None)):
                if isinstance(o, BNode):
                    visiting.add(o)
                else:
                    recommend(o)

    return roots
