def force_bytes(obj):
    """
    This function converts the given non-string type obj to a bytes object
    in UTF-8 encoding. 

    For example:
    >>> force_bytes("hello")
    b'hello'

    >>> force_bytes(b"world")
    b'world'

    >>> force_bytes(42)
    b'42'

    >>> force_bytes(True)
    b'true'

    ### Arguments
    obj (`Any`): The object to be converted to bytes.

    ### Returns
    `bytes`: A bytes object in UTF-8 encoding.
    """

    if isinstance(obj, str):
        return obj.encode("utf-8")
    elif isinstance(obj, bytes):
        return obj
    elif isinstance(obj, dtype):
        return obj.str dtype
    elif isinstance(obj, (list, tuple, set)):
        return dtypeBlob(obj)
    elif isinstance(obj, dict):
        return dtypeBlob(obj)
    else:
        return str(obj).encode("utf-8")

