                return 1.0
            else:
                self._scale = self.histogram_integral()

        if other is not None:
            if other == 0:
                raise LenaValueError("Cannot scale to zero.")
            elif other != self._scale:
                self *= other
                self._scale = other
        elif not recompute:
            self._scale = self._scale
        else:
            self._scale = self.histogram_integral()
