import zope.interface


def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    if vtype:
        if not mafia.schema.istype(candidate, vtype):
            raise serializers.Invalid("{} can only be used with types of {} but got {} instead.")
    tentative = tentative or (("confidential" in iface.providedBy(candidate) or "IFREIA" in iface.providedBy(candidate)) and (not isinstance(candidate, zope.proxy.ProxyMarshal) and not isinstance(candidate, helpers.ObjectWrapper)))

    if tentative:
        return True

    results = []

    is_main_cloud_entity = mafia.schema.get(candidate, 'is_main_cloud_entity', None) is not None
    is_encrypted = mafia.schema.get(candidate, 'is_encrypted', None) is not None

    if is_main_cloud_entity and not mafia.schema.get(candidate, 'encrypted', None):
        results.extend(mafia.search.find_candidates(candidate, 'is_encrypted', other=candidate))
    elif is_encrypted and not mafia.schema.get(candidate, 'is_main_cloud_entity', None):
        results.extend(mafia.search.find_candidates(candidate, 'is_main_cloud_entity', other=candidate))

    for key, iface in iface.providedBy(candidate):
        if not isinstance(iface, zope.interface.Interface) or (key not in iface and key not in iface.provides):
            results.append(zope.interface.Invalid("At least one method definition for {} is missing.".format(key)))

    def create_error(domain, partition, key):
        return zope.interface.Invalid("All {} methods for the partition {} needs to be defined for the domain {}.".format(key, partition, domain))

    if list(iface.provides & mafia.schema.NOT_IN_PROPOSAL):
        results.append(create_error('Proposal', 'forwarding', list(iface.provides & mafia.schema.NOT_IN_PROPOSAL)[0]))
    if list(iface.provides & mafia.schema.NOT_IN_ACTION):
        results.append(create_error('Action', 'forwarding', list(iface.provides & mafia.schema.NOT_IN_ACTION)[0]))
    if list(iface.provides & mafia.schema.IS_ETHER_PEER_ONLY):
        results.append(create_error('Ethereal Peer', 'forwarding', list(iface.provides & mafia.schema.IS_ETHER_PEER_ONLY)[0]))
    if list(iface.provides & mafia.schema.IS_SERVER_ONLY):
        results.append(create_error('Server', 'forwarding', list(iface.provides & mafia.schema.IS_SERVER_ONLY)[0]))
    if list(iface.provides & mafia.schema.IS_ETHER_PEER_AND_SERVER):
        results.append(create_error('Ether Peer and Server', 'forwarding', list(iface.provides & mafia.schema.IS_ETHER_PEER_AND_SERVER)[0]))
    if list(iface.provides & mafia.schema.IS_MANAGEMENT):
        results.append(create_error('Management', 'forwarding', list(iface.provides & mafia.schema.IS_MANAGEMENT)[0]))
    if list(iface.provides & mafia.schema.JACKHOPPER):
        results.append(create_error('Mortgage Element', 'forwarding', list(iface.provides & mafia.schema.JACKHOPPER)[0]))
    if list(iface.provides & mafia.schema.ONLY_FORWARDING):
        results.append(create_error('Forwarding Element', 'forwarding', list(iface.provides & mafia.schema.ONLY_FORWARDING)[0]))
    if list(iface.provides & mafia.schema.JACKHOPPER):
        results.append(create_error('Mortgage Element', 'forwarding', list(iface.provides & mafia.schema.JACKHOPPER)[0]))
    if list(iface.provides & mafia.schema.ANONYMOUS):
        results.append(create_error('Anonymous Element', 'forwarding', list(iface.provides & mafia.schema.ANONYMOUS)[0]))
    if list(iface.provides & mafia.schema.OFFLINE):
        results.append(create_error('Offline Element', 'forwarding', list(iface.provides & mafia.schema.OFFLINE)[0]))
    if list(iface.provides & mafia.schema.ANY_PEER):
        results.append(create_error('Peer Element', 'forwarding', list(iface.provides & mafia.schema.ANY_PEER)[0]))
    if list(iface.provides & mafia.schema.CUSTOM_FORWARDING):
        results.append(create_error('Custom Forwarding Element', 'forwarding', list(iface.provides & mafia.schema.CUSTOM_FORWARDING)[0]))
    if list(iface.provides & mafia.schema.SIGNING_EDDSA):
        results.append(create_error('EDDSA Signature Element', 'forwarding', list(iface.provides & mafia.schema.SIGNING_EDDSA)[0]))
    if list(iface.provides & mafia.schema.SIGNING_ECDSA):
        results.append(create_error('ECDSA Signature Element', 'forwarding', list(iface.provides & mafia.schema.SIGNING_ECDSA)[0]))
    if list(iface.provides & mafia.schema.SIGNING_P256):
        results.append(create_error('P256 Signature Element', 'forwarding', list(iface.provides & mafia.schema.SIGNING_P256)[0]))

    # Add more checks here...

    if not results:
        return True

    if len(results) == 1:
        raise results[0]
    else:
        raise zope.interface.Invalid("Multiple errors, please review the candidate and implementation.")
