    if tentative and not iface.providedBy(candidate):
        return True

    if not isinstance(candidate, iface.providedBy(candidate) | iface):
        raise Invalid("The candidate does not provide the specified interface.")

    methods = iface.implementedBy(candidate)
    if not methods and iface.suppliedBy(candidate):
        methods = iface.suppliedBy(candidate)
    for m in methods:
        if not hasattr(candidate, m):
            raise Invalid("Method %s not defined" % m.__name__)

    attributes = iface.attributesByProvidingInterface(candidate)
    for attr, requirements in attributes.items():
        if not hasattr(candidate, attr) and requirements:
            raise Invalid("Attribute %s not defined or required by interface" % attr)

