def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    if explicit_mc is not None:
        return explicit_mc

    # Check for multiple bases
    if len(bases) > 1:
        raise ValueError("Cannot determine metaclass more than once with multiple types")

    base = bases[0]

    if hasattr(base, '__metaclass__'):
        # Special case for non-stellar models
        if base.__class__.__name__ == 'GPModel':
            return StellarModelMeta
        # Default to the metaclass of the base class
        return base.__metaclass__
    else:
        # Default to default metaclass
        return DefaultMeta
