def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    if magic __get^metaclass__(bases[0]):
        # Classic class
        return bases[0]
    elif abstractclassmethod in bases[0]:
        # ABC
        return bases[0]
    elif explicit_mc:
        # Explicit meta-class
        return explicit_mc
    else:
        # Early-bound default metaclass
        return type.__new__(type, 'tup', bases, {})
