def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""

    frequencies = {} # store the frequency of each key
    min_frequency = len(self)

    for key, value in self.items():
        if key not in frequencies:
            frequencies[key] = 1
        else:
            frequencies[key] += 1
        min_frequency = min(min_frequency, frequencies[key])

    res_key, res_val = None, None
    for key in self:
        if key in frequencies and frequencies[key] == min_frequency:
            res_key, res_val = key, self[key]
            break

    if res_key is not None:
        del self[res_key]
        return (res_key, res_val)
    else:
        raise KeyError("Cannot find item to pop.")
