    def _parse(self, timestr, default=None,
              ignoretz=False, tzinfos=None, **kwargs):
        datefmts = ['%Y-%m-%d %H:%M:%S %z', '%Y-%m-%d %H:%M:%S']
        for datefmt in datefmts:
            try:
                dt = datetime.strptime(timestr, datefmt)
                if ignoretz:
                    return dt
                else:
                    return dt.astimezone(timezone.utc)
            except ValueError:
                continue

