def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tag_set = set()
    result_text = ""

    depth = 0
    in_code_block = False

    for char in text:
        # Check for opening code block
        if char == '<' and depth == 0 and not in_code_block:
            in_code_block = True
        # Check for closing code block
        elif char == '>' and depth == 1 and in_code_block:
            in_code_block = False
        # Increase depth for nested tags
        elif depth < 0:
            depth += 1
        # Reduce depth for nested tags
        elif char == '/' and depth > 0:
            depth -= 1
        # Check for a tag boundary
        elif (char == '<' or char == '>') and (depth == 0 and not in_code_block):
            if replacer is not None:
                result_text += replacer(char)
            else:
                result_text += char
        # Add to tag set
        elif char != '<' and char != '>' and (depth == 0 and not in_code_block):
            tag_set.add(char)

    return tag_set, result_text
