def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    if not signature or not public_key or not doc:
        if doc:
            raise ValueError("Signature must be provided.")
        raise ValueError("Public key must be provided.")
        raise ValueError("Document must be provided.")

    # Verify the signature using the public key
    try:
        verified = doc.verify_signature(public_key, signature)
    except Exception as e:
        raise ValueError("Failed to verify signature: " + str(e))

    if verified:
        return True
    else:
        raise ValueError("Signature verification failed.")
