    @classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("Missing required spec content")
        disabled = set()
        keys_unexpectedly_supplied = set()
        keys_missing = set()

        for key, value in spec_content.items():
            if key == 'disabled':
                if isinstance(value, bool):
                    disabled.add(value)
                else:
                    keys_missing.add(key)
            elif key not in cls.REQUIRED_ATTRIBS:
                keys_unexpectedly_supplied.add(key)
            else:
                if key in cls.REQUIRED_VALUES:
                    value = validate_value(value, cls.REQUIRED_VALUES[key])
                if isinstance(value, str) and not value:
                    keys_missing.add(key)

        if not disabled:
            disabled = None

        if keys_unexpectedly_supplied:
            raise IRValidatorException("Unrecognized keys: " + ', '.join(keys_unexpectedly_supplied))

        if keys_missing:
            raise IRValidatorException("Missing required keys: " + ', '.join(keys_missing))

        return spec_content
