def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files. """

    if not parser_dict:
        self.invalidparserdict(True)
        self.abort()

    try:
        groups = self.xml().children('dict_group')
        for group in groups:
            if group.name != 'dict_group':
                raise ValueError(f"Invalid group tag in {self.path}: {group.name} (expected 'dict_group')")
            group_id = group.attribute('id')
            if not group_id:
                raise ValueError(f"Missing id attribute in group {group.tag} at {self.path}")
            if self.get_group(group_id):
                raise ValueError(f"Group {group_id} already exists at {self.path}")
            self.create_group(group_id)
            include_path = group.attribute('include')
            if not include_path:
                raise ValueError(f"Missing include attribute in group {group.tag} at {self.path}")
            include_resource_type = group.attribute('resource_type')
            if not include_resource_type:
                include_resource_type = 'text'
            include_target = IncludeTarget(self.xml().string(), include_resource_type)
            self.include_group(group_id, include_path, include_resource_type, include_target)
    except Exception as e:
        self.render_log(f"Error while including groups at {self.path}: {e}")
        self.abort()
