def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
       """


    if not parser_name:
        raise ValueError("Parser name can't be empty")
    if not values_dict:
        raise ValueError("Values dictionary can't be empty")

    # modify values_dict to convert types to correct types
    for key, value in values_dict.items():
        if value is None:
            continue
        if isinstance(value, list):
            for i in range(len(value)):
                if isinstance(value[i], str):
                    value[i] = convert_to_type(value[i], 'list')
        elif isinstance(value, str):
            value = convert_to_type(value, 'string')
        elif isinstance(value, bool):
            value = convert_to_type(value, 'bool')
        elif isinstance(value, int):
            value = convert_to_type(value, 'int')
    return values_dict
